import translation_client

def translate_dictionary_values(dictionary, source_language, target_language, config=None):
    client = translation_client.TranslationClient(config)
    translated_dictionary = {}
    for key, value in dictionary.items():
        translation = client.translate_text({'text': value, 'source_language': source_language, 'target_language': target_language})
        translated_dictionary[key] = translation['text']
    return {'dictionary': translated_dictionary, 'source_language': source_language, 'target_language': target_language}

import os
import requests

class TranslationClient:
    def __init__(self, config=None):
        self.config = config or {}
        self.api_key = self.config.get('api_key', os.getenv('TRANSLATOR_API_KEY'))
        self.region = self.config.get('region', os.getenv('TRANSLATOR_REGION'))

    def translate_text(self, payload):
        response = requests.post('https://api.cognitive.microsofttranslator.com/translate',
            headers={'Ocp-Apim-Subscription-Key': self.api_key,
                     'Ocp-Apim-Subscription-Region': self.region},
            params={'api-version': '3.0', 'from': payload['source_language'], 'to': payload['target_language']},
            json=[{'Text': payload['text']}], timeout=30)
        response.raise_for_status()
        return {'text': response.json()[0]['translations'][0]['text'],
                'source_language': payload['source_language'], 'target_language': payload['target_language']}

def normalize_payload(payload):
    return {'text': payload['text'], 'source_language': payload['source_language'], 'target_language': payload['target_language']}

def normalize_response(response):
    return {'text': response['text'], 'source_language': response['source_language'], 'target_language': response['target_language']}

import re
import translation_client

def unsafe_copy_check(translation):
    client = translation_client.TranslationClient()
    unsafe_patterns = [r'\b(badword1|badword2|badword3)\b']
    for pattern in unsafe_patterns:
        if re.search(pattern, translation['text'], re.IGNORECASE):
            return {'unsafe': True, 'text': translation['text'], 'source_language': translation['source_language'], 'target_language': translation['target_language']}
    return {'unsafe': False, 'text': translation['text'], 'source_language': translation['source_language'], 'target_language': translation['target_language']}

